<?php

namespace App\Livewire;

use App\Models\SchoolSetting;
use App\Models\Student;
use App\Models\Term;
use App\Models\User;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Mail;
use Livewire\Attributes\Layout;
use Livewire\Component;
use Livewire\WithFileUploads;

#[Layout('layouts.app')]
class SchoolSettings extends Component
{
    use WithFileUploads;
    public string $name = '', $email = '', $phone = '', $address = '', $motto = '', $website = '', $principal_name = '';
    public $badge = null;
    public array $settings = [];
    public $closedTerms;
    public $reviewTermId = '';
    protected array $keys = ['receipt_footer','currency','number_format','admission_prefix','payment_methods','payment_receipt_email_enabled','mobile_money_details','bank_details','cash_pool_opening_balance','arrears_rule','term_closing_rule','payroll_approval_rule','academic_year_rule','grading_scale','promotion_rule','max_class_progression','required_student_fields','student_status_rules','staff_number_format','roles_permissions','payroll_period','leave_types','leave_approval_rule','sender_name','email_provider','sms_provider','arrears_email_template','arrears_email_reminders_enabled','notification_schedule','notification_daily_attendance_enabled','notification_subject_attendance_enabled','notification_homework_enabled','notification_homework_feedback_enabled','notification_results_enabled','otp_enabled','audit_retention','backup_export_rule','timezone','date_format','language','certificate_title','certificate_subtitle','certificate_intro','certificate_achievement','certificate_signatory_name','certificate_signatory_title','certificate_number_prefix','recommendation_title','recommendation_intro','recommendation_body','recommendation_closing'];

    public function mount(): void { $school=Auth::user()->school; foreach(['name','email','phone','address','motto','website','principal_name'] as $key) $this->{$key}=$school->{$key}??''; $stored=SchoolSetting::where('school_id',$school->id)->pluck('value','key')->all(); foreach($this->keys as $key) $this->settings[$key]=$stored[$key]??$this->default($key); $this->closedTerms=Term::where('school_id',$school->id)->where('status','closed')->latest('closed_at')->get(); $this->reviewTermId=$stored['term_review_id']??''; }
    protected function default(string $key): string { return match($key) { 'currency'=>'UGX','number_format'=>'1,234.56','payment_methods'=>'cash,mobile_money,bank','payment_receipt_email_enabled'=>'enabled','academic_year_rule'=>'Three terms per academic year','payroll_period'=>'Monthly','timezone'=>'Africa/Kampala','date_format'=>'d M Y','language'=>'English','arrears_email_template'=>'Dear {parent_name}, this is a reminder that {student_name} has an outstanding school fee balance of {amount} at {school_name} for {term}. Please arrange payment at your earliest convenience.','arrears_email_reminders_enabled'=>'disabled','otp_enabled'=>'enabled','notification_daily_attendance_enabled','notification_subject_attendance_enabled','notification_homework_enabled','notification_homework_feedback_enabled','notification_results_enabled'=>'enabled','certificate_title'=>'Certificate of Completion','certificate_subtitle'=>'Awarded with distinction and pride','certificate_intro'=>'This certificate is proudly presented to','certificate_achievement'=>'For successfully completing the prescribed course of study with dedication and commitment.','certificate_signatory_title'=>'Head Teacher','certificate_number_prefix'=>'CERT','recommendation_title'=>'Letter of Recommendation','recommendation_intro'=>'To Whom It May Concern','recommendation_body'=>'We are pleased to recommend this graduate, who completed their studies at our institution with commitment, discipline, and good standing.','recommendation_closing'=>'We confidently recommend them for further study and suitable opportunities.',default=>''}; }
    public function save(): void { $this->validate(['name'=>'required|string|max:255','email'=>'nullable|email','website'=>'nullable|url','badge'=>'nullable|image|max:2048','settings.arrears_email_reminders_enabled'=>'required|in:enabled,disabled','settings.notification_daily_attendance_enabled'=>'required|in:enabled,disabled','settings.notification_subject_attendance_enabled'=>'required|in:enabled,disabled','settings.notification_homework_enabled'=>'required|in:enabled,disabled','settings.notification_homework_feedback_enabled'=>'required|in:enabled,disabled','settings.notification_results_enabled'=>'required|in:enabled,disabled']); $school=Auth::user()->school; $school->update(['name'=>$this->name,'email'=>$this->email?:null,'phone'=>$this->phone?:null,'address'=>$this->address?:null,'motto'=>$this->motto?:null,'website'=>$this->website?:null,'principal_name'=>$this->principal_name?:null,'badge_path'=>$this->badge?$this->badge->store('school-badges','public'):$school->badge_path]); foreach($this->keys as $key) SchoolSetting::updateOrCreate(['school_id'=>$school->id,'key'=>$key],['value'=>$this->settings[$key]??null]); session()->flash('status','System settings saved.'); }
    public function sendFeeReminders(): void { abort_unless(Auth::user()->hasPermission('settings.manage'),403); $school=Auth::user()->school; $term=Term::currentFor($school); if(!$term){session()->flash('error','Open an academic term before sending fee reminders.');return;} $template=$this->settings['arrears_email_template']?:$this->default('arrears_email_template'); $sent=0;$emails=0; foreach(Student::with('guardians')->where('school_id',$school->id)->where('status','active')->get() as $student){$balance=max(0,(float)$student->balance($term));if($balance<=0)continue;$recipients=User::where('school_id',$school->id)->where('role','parent')->whereHas('portalStudents',fn($q)=>$q->where('students.id',$student->id))->get();$recipientEmails=$recipients->pluck('email')->merge($student->guardians->pluck('email'))->filter(fn($email)=>is_string($email)&&filter_var($email,FILTER_VALIDATE_EMAIL))->unique()->values();foreach($recipients as $parent){$message=str_replace(['{parent_name}','{student_name}','{amount}','{school_name}','{term}'],[$parent->name,$student->name,number_format($balance,2),$school->name,$term->name.', '.$term->year],$template);DB::table('school_notifications')->insert(['school_id'=>$school->id,'user_id'=>$parent->id,'student_id'=>$student->id,'title'=>'Fee payment reminder','message'=>$message,'type'=>'warning','category'=>'fee_reminder','created_at'=>now(),'updated_at'=>now()]);$sent++;}if($this->settings['arrears_email_reminders_enabled']==='enabled')foreach($recipientEmails as $email){$message=str_replace(['{parent_name}','{student_name}','{amount}','{school_name}','{term}'],['Parent/guardian',$student->name,number_format($balance,2),$school->name,$term->name.', '.$term->year],$template);Mail::raw($message,fn($mail)=>$mail->to($email)->subject('Fee payment reminder · '.$student->name));$emails++;}}session()->flash('status',"Fee reminders sent to {$sent} parent account(s)".($this->settings['arrears_email_reminders_enabled']==='enabled'?" and {$emails} email recipient(s).":'. Email reminders are disabled in settings.')); }
    public function enableTermReview(int $termId): void { abort_unless(Auth::user()->hasPermission('settings.manage'),403); $school=Auth::user()->school; $term=$school->terms()->whereKey($termId)->where('status','closed')->firstOrFail(); SchoolSetting::setValue($school->id,'term_review_id',(string)$term->id); session()->flash('status',"{$term->name} {$term->year} is now available in read-only review mode for authorized users."); }
    public function disableTermReview(): void { abort_unless(Auth::user()->hasPermission('settings.manage'),403); SchoolSetting::where('school_id',Auth::user()->school_id)->where('key','term_review_id')->delete(); session()->flash('status','Closed-term review mode has been turned off.'); }
    public function render(){return view('livewire.school-settings',['pageTitle'=>'System Settings']);}
}
